using System.Linq;using NUnit.Framework;using UnityEditor;using Rootborn.Game.Common;namespace Rootborn.Tests.EditMode.UI{public sealed class UtilityTextDataAssetTests{GameDataRegistry Registry=>AssetDatabase.LoadAssetAtPath<GameDataRegistry>("Assets/Data/Registry/GameDataRegistry.asset");void Localized(string key){Assert.That(key,Is.Not.Null.And.Not.Empty);var cat=Registry.TextCatalog;var ko=cat.Get(key,"ko");Assert.That(ko.Any(c=>c>=0xAC00&&c<=0xD7A3),Is.True,"Missing Korean authored text for "+key);Assert.That(cat.Get(key,"en"),Is.Not.EqualTo(key),"Missing English authored text for "+key);}[Test]public void AllRegisteredWorldChangesHaveDistinctReadableTitlesDescriptionsAndNextActions(){foreach(var flag in Registry.WorldStateFlags.Where(f=>f!=null)){Localized(flag.DisplayNameKey);Localized(flag.DescriptionKey);Localized(flag.NextActionKey);Assert.That(Registry.TextCatalog.Get(flag.DescriptionKey,"ko"),Is.Not.EqualTo(Registry.TextCatalog.Get(flag.DisplayNameKey,"ko")),"World history must explain the change instead of repeating its title");}}[Test]public void EncyclopediaCategoriesAndEntryDetailsUsePlayerFacingBilingualText(){foreach(var c in Registry.EncyclopediaCategories.Where(x=>x!=null))Localized(c.DisplayName);foreach(var e in Registry.EncyclopediaEntries.Where(x=>x!=null)){Localized(e.DisplayName);Localized(e.Description);Localized(e.LockedHint);foreach(var line in e.DetailLines){Localized(line);string value=Registry.TextCatalog.Get(line,"en");Assert.That(value,Does.Not.Contain("persisted").And.Not.Contain("from data"));}Assert.That(Registry.TextCatalog.Get(e.Description,"en"),Does.Not.Contain("verify category"));}}}}